def re_arrange_array(arr):
    # Partition the array so that all negative numbers come before positives
    i = 0
    for j in range(len(arr)):
        if arr[j] < 0:
            arr[i], arr[j] = arr[j], arr[i]
            i += 1
    return arr

def second_smallest(lst):
    if len(lst) < 2:
        raise ValueError("List must contain at least two elements")
    first = second = float('inf')
    for num in lst:
        if num < first:
            second = first
            first = num
        elif first < num < second:
            second = num
    if second == float('inf'):
        raise ValueError("No second smallest element found")
    return second

import re

def remove_multiple_spaces(s: str) -> str:
    return re.sub(r'\s+', ' ', s)

def max_sub_array_sum(arr):
    max_ending_here = max_so_far = arr[0]
    for x in arr[1:]:
        max_ending_here = max(x, max_ending_here + x)
        max_so_far = max(max_so_far, max_ending_here)
    return max_so_far

def len_log(words):
    """Return the length of the longest word in the input iterable of words."""
    if not words:
        return 0
    return max(len(word) for word in words)

from typing import List, Tuple

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    total_sum = sum(numbers)
    product = 1
    for num in numbers:
        product *= num
    return (total_sum, product)

def words_in_sentence(sentence):
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    prime_length_words = [word for word in words if is_prime(len(word))]
    return " ".join(prime_length_words)

